import{_ as a,o as r,c as e,a2 as i}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"家长端快速开始","description":"家长如何绑定孩子并使用小程序","frontmatter":{"title":"家长端快速开始","description":"家长如何绑定孩子并使用小程序"},"headers":[],"relativePath":"miniprogram/quickstart.md","filePath":"miniprogram/quickstart.md","lastUpdated":1791175383000}'),o={name:"miniprogram/quickstart.md"};function l(d,t,s,n,h,c){return r(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="快速开始-家长" tabindex="-1">快速开始（家长） <a class="header-anchor" href="#快速开始-家长" aria-label="Permalink to &quot;快速开始（家长）&quot;">​</a></h1><h2 id="家长-三步绑定" tabindex="-1">家长：三步绑定 <a class="header-anchor" href="#家长-三步绑定" aria-label="Permalink to &quot;家长：三步绑定&quot;">​</a></h2><ol><li><strong>拿到邀请码</strong>：教师在班级里批量生成 6 位邀请码并发放（通常打印在通知条上）</li><li><strong>打开小程序</strong>：微信搜索 AgoraIn 家长端，或扫描学校提供的小程序码</li><li><strong>输入邀请码</strong>：选择「绑定孩子」→ 输入 6 位邀请码 → 绑定成功</li></ol><p>绑定后即可看到通知、值日、班级资源与留言入口；成绩概览需学校开启后可见。</p><h2 id="教师-怎么发邀请码" tabindex="-1">教师：怎么发邀请码 <a class="header-anchor" href="#教师-怎么发邀请码" aria-label="Permalink to &quot;教师：怎么发邀请码&quot;">​</a></h2><ol><li>后台「学生」→ 选择班级 → <strong>批量生成邀请码</strong></li><li>点击「导出 CSV」拿到全班邀请码清单（含学生姓名），打印后发放</li><li>家长绑定后，「学生」列表会显示已绑定的家长数量</li></ol><div class="tip custom-block"><p class="custom-block-title">邀请码规则</p><p>邀请码为 6 位、一码一学生、可重复使用于同一孩子的多个家长（父母可各绑一次）。 学生转班或毕业时可在后台作废重建。</p></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>处理</th></tr></thead><tbody><tr><td>提示邀请码无效</td><td>确认是否已作废或输错；请教师重新生成</td></tr><tr><td>看不到成绩</td><td>学校未开启成绩概览（默认关闭），请联系班主任</td></tr><tr><td>绑定错了孩子</td><td>在「我的 → 孩子管理」申请解绑，或联系教师处理</td></tr><tr><td>收不到通知</td><td>检查微信通知权限；小程序内下拉刷新</td></tr></tbody></table><h2 id="相关阅读" tabindex="-1">相关阅读 <a class="header-anchor" href="#相关阅读" aria-label="Permalink to &quot;相关阅读&quot;">​</a></h2><ul><li><a href="/miniprogram/features.html">功能特性</a> · <a href="/faq.html">常见问题</a></li></ul>',11)])])}const u=a(o,[["render",l]]);export{p as __pageData,u as default};
